    background: "后唐天成二年（927），赵匡胤生于洛阳夹马营的军人世家。祖籍涿郡，父赵弘殷历事后唐、后晋、后汉、后周四朝，官至检校司徒、天水县男，典掌禁卫。赵匡胤少年习武，善骑射，曾驯烈马不施衔勒，触门楣坠地而复起追之，人服其勇。后汉乾祐年间，他离洛南游，穷困无所遇，遂北投枢密使郭威帐下，从征河中李守贞，始得军功之阶。广顺元年（951）郭威代汉建周，他渐受拔擢。显德元年（954）周世宗柴荣即位，北汉乘丧合契丹南下，战于高平；周军右阵主将樊爱能、何徽临阵遁逃，势几危，赵匡胤时为殿前散员都虞候，与张永德各率二千人奋击，大破北汉，自此崭露头角，深得柴荣信用。显德六年（959）柴荣北征辽国，军中得木牌书「点检作天子」，遂以赵匡胤代张永德为殿前都点检，执掌后周最精锐之禁军。未几世宗英年早逝，年三十九。显德七年（960）正月，幼主柴宗训年方七岁继位，主少国疑，京师流言四起，朝局暗潮汹涌，兵变之机已熟。",
