    interpretation: "太祖受禅，看似一夕之事，实为五代兵权流转之必然：自安史之乱后，节镇专兵，梁、唐、晋、汉、周更替多由禁军拥立，郭威如此，赵匡胤亦如此，陈桥兵变不过是这一循环的最后一环。真正不同者，在于太祖得位后不再以兵制驭兵，而以制度分兵：三衙分掌禁军，更戍使兵将分离，通判连署州事，转运使敛财于上，节度使渐成虚衔。自此将不得专其兵，兵不得私其将，五代武人乱政之循环至宋而绝，国祚遂得三百一十九年。其重文轻武、强干弱枝的家法，上承誓碑「不得杀士大夫及上书言事人」之训，开文治昌明之局，士大夫得行己志，宋学、宋文彬彬称盛；然矫枉过正，武备积弱，外患不绝，终有靖康之变。烛影斧声一夕传位于弟，金匮之盟、烛影之说聚讼千年，要之皆见其家法以「防弊」为心，宫闱之防终不越制度之防，此太祖之深意，亦宋室之宿命。",
