    interpretation: "仁宗在位四十二年，上承真宗之宽纵，下启英宗、神宗之更化，是两宋政治史上承前启后的关键时代。其最大特点，在于皇帝与士大夫共治格局的定型：台谏得以风闻言事，宰执进退取决于公论，皇权受制度与清议的双重约束，包拯唾面而帝不怒、唐介忤旨而终得复用，皆其显例。然宽仁之极，亦伏因循之弊：三冗始终未除，财政危机至嘉祐已深，庆历新政因触犯既得利益而中废，改革只能留待神宗朝王安石变法。对外，庆历和议与对辽增币，以岁币岁赐换和平，宋辽之间「四十二年不识兵革」，百姓得安，而国防之弱亦种因于此。论者或誉其宽厚清明，或病其柔弱无断，要之，赵祯以一人之仁，成一代名臣、一代文化，《宋史》「为人君，止于仁」之赞，实为定论。",
