    interpretation: "赵佶的一生，是艺术天才与政治庸主的极端合体。他以一己之力把宋代美学推向巅峰：瘦金体书法、宣和画谱、画院制度、艮岳园林，至今仍是中华艺术史上的高峰；但他把这些审美活动建立在搜刮天下的基础上，苏杭应奉局与花石纲把东南逼出方腊之乱，丰亨豫大之说掏空了国家财政。政治上，他以「绍述」为名行钳制之实，元祐党人碑三百零九人株连子孙，自毁元祐以来的人才储备；又好大喜功，定海上之盟联金灭辽，两路北伐皆败，反使金人看穿虚实，自撤辽国这一南北屏障，终招靖康之祸。其即位时章惇「端王轻佻，不可以君天下」之言，竟成一语成谶。赵佶的悲剧说明：帝王的个人才华若无治国责任与之相称，则才华愈高，为害愈烈，北宋之亡，非亡于金，实先亡于内。",
