          "元丰八年（1085）三月，神宗崩，哲宗即位，高太后垂帘听政，起用司马光为相。司马光执政后尽罢新法，免役、青苗诸法次第被废，史称「元祐更化」。元祐元年（1086）四月，王安石在江宁闻新法尽废，忧愤成疾，病逝于半山园，享年六十六岁。朝廷追赠太傅，谥曰「文」，故后人称「王文公」。哲宗亲政后绍述新法，但北宋国势已衰。变法虽成往事，「天变不足畏，祖宗不足法，人言不足恤」的改革精神，至今仍回响在历史长河之中。"
