    interpretation: "王安石变法是中国古代规模最大、设计最系统的改革之一。其核心是以国家力量介入经济，把豪强、商贾手中的利权收归朝廷，借此充实国库、整军备边。从财政效果看，新法确实使元丰年间府库充盈、西北拓地千里；但从执行看，青苗、免役诸法本为济贫弱、平徭役，在地方官手中却常变成强行摊派、催科索利，民怨由此而生。变法成败的关键不在制度条文，而在吏治与用人——王安石信赖的吕惠卿、曾布等人后来多背公营私，正坐此弊。新旧党争由政见之争演为意气之争，倾轧四十余年，耗尽北宋元气。南宋以后王安石评价长期走低，至近代梁启超著《王安石传》始为之翻案。其「三不足」精神，上承商鞅，下启张居正，成为中国古代改革者最硬的一根脊梁。",
