    summary: "北宋政治家、史学家，《资治通鉴》主编。字君实，陕州夏县涑水乡人，世称涑水先生；宝元元年（1038）登进士甲科。与王安石为新旧党争的两极：新法既行，坚辞枢密副使，退居洛阳十五年专意修史；元丰七年（1084）《资治通鉴》成书，凡二百九十四卷，记事上起周威烈王二十三年（前403），下迄后周显德六年（959），凡一千三百六十二年，是中国编年体通史的巅峰。元丰八年神宗崩，哲宗幼冲，高太后临朝，起为宰相，元祐更化，尽罢新法；元祐元年（1086）九月卒于位，年六十八，赠太师、温国公，谥文正。",
    background: "司马光（1019—1086），字君实，陕州夏县涑水乡人，故世称涑水先生。父司马池官至兵部郎中、天章阁待制，以清直称。司马光七岁闻讲《左氏春秋》，即了其大义，手不释卷；《宋史》载其幼年「凛然如成人」。北宋此时正值积贫积弱之秋：冗官、冗兵、冗费交叠，西夏、契丹岁币为患，朝野议论蜂起，士大夫多怀变法图强之志。宝元元年（1038），司马光登进士甲科，年方二十，除奉礼郎，历大理评事、国子直讲，经庞籍荐通判并州，亲历边防；嘉祐中入为起居舍人、同知谏院，上章论建储、节用、罢冗兵。治平三年（1066），进所编《历年图》及《通志》八卷，英宗览而善之，命设局崇文院续修——此即《资治通鉴》之发端。",
