          "熙宁三年（1070），神宗欲大用司马光，除枢密副使。司马光连上六七道札子坚辞不拜，自陈：朝廷用臣，当使臣得行其言；言既不用而窃高位，是负陛下之任。神宗遣内使至其第趣受诰命，司马光封还诰身，终不肯拜。神宗不得已听其外补，乃出知永兴军（今陕西西安）。其时陕西方议进筑横山以逼西夏，司马光到任后上疏，力陈军兴劳费、转输困乏，主张持重守御，与主战者再次相左；在任一年，即请闲职。",
