        paragraphs: [
          "《资治通鉴》之修，始于治平三年（1066）。司马光以《通志》八卷上进，记战国至秦二世二百三十年事，英宗命接续纂修，许自选官属、辟置书局于崇文院。神宗即位，览其书而器之，赐名《资治通鉴》，亲制序文，许以「鉴于往事，有资于治道」——此语后追述于司马光《进资治通鉴表》中——又以颍邸旧书二千四百卷赐之。神宗特许书局随司马光迁转，开封、洛阳皆可设局，修书之事遂不因外补而中辍。",
          "《资治通鉴》非一人之力可成。司马光辟刘攽（贡父）、刘恕（道原）、范祖禹（淳甫）为同修官：刘攽精两汉，主汉史长编；刘恕博闻强记，主三国两晋南北朝；范祖禹专唐史，兼及五代。其法先作丛目，广搜史料编年系事；次作长编，宁繁毋略；最后由司马光一手笔削润色、删定成书。异同疑碍之处，别为《考异》三十卷，并存诸说、辨明真伪，开史料考证之先河。司马光总揽大纲，事必躬亲，删稿残页堆积盈屋；又以圆木为警枕，少憩即觉，觉而复书。",
          "元丰七年（1084）十二月，《资治通鉴》全书奏进，凡二百九十四卷，并《目录》三十卷、《考异》三十卷。书上起周威烈王二十三年（公元前403年）三家分晋，下迄后周世宗显德六年（公元959年），记一千三百六十二年之事，是中国编年体通史的巅峰。司马光在《进资治通鉴表》中自述：「臣之精力，尽于此书。」十九年间，他食不甘味、寝不安席；书成之日，须发尽白，齿落目昏。两年之后，他便溘然长逝，可谓以命殉史。"
        ]
