    interpretation: "司马光之史学与政见，实为一体两面。他主张礼治、名分、纳谏、节用，视新法为与民争利，故《资治通鉴》取材以「关国家兴衰，系生民休戚」为准，详治乱而略琐闻；其《考异》三十卷并存诸说、辨明真伪，开史料考证之先河。然元祐更化尽废新法，未及救弊，已开党争倾轧之局：司马光身后，哲宗亲政行绍述，元祐党人贬窜无遗，北宋国势终困于党争。司马光立朝清直自守，「平生所为，未尝有不可对人言者」；其书上接《春秋》，下启《通鉴纲目》之学，胡三省为之作注，王夫之衍为《读通鉴论》。其人其书，遂为北宋士大夫立身与立言的两座高峰。",
