    interpretation: "岳飞之死，不是一桩孤立的冤狱，而是南宋政治结构内在矛盾的产物。南宋立国江左，既要依仗武将抵御金人，又始终猜忌武将权重难制，唯恐重演唐末藩镇与五代兵变之祸。高宗南渡之际，苗刘之变、淮西兵变更使他对握兵之将深怀戒惧。岳飞拥兵十万，联结河朔，功盖诸将，又力主迎还二帝、恢复中原，在主和派看来，既是和议的障碍，也是皇权的隐患。秦桧不过是迎合帝意、操刀其事之人。所谓「莫须有」，正是皇权屈枉司法、以收兵权重于保江山的写照。从军事上看，岳飞以步制骑、联结河朔的战法，使南宋首次具备正面战胜金军主力的能力。郾城、颍昌两役证明金军并非不可战胜，若非十二道金牌班师，收复东京并非全无可能。岳飞死后，南宋再无大规模北伐的实力与心气，偏安格局遂定；而其含冤而死，反使他在民间获得近乎神圣的地位，岳王庙香火不绝，成为后世忠义气节的最高象征。一个王朝自毁长城，其代价是永远无法追回的。",
