    interpretation: "李清照的意义不止于「婉约词宗」四字。她以女性身份进入由男性垄断的士大夫书写领域，其《词论》批评晏殊、欧阳修、苏轼诸公，提出词「别是一家」，是中国文学批评史上第一篇系统的词学专论。她的遭遇也是两宋之交士人命运的缩影：靖康之变摧毁了北宋积累百年的文化体系，青州故第十余屋书册金石毁于兵火，正是那个时代典籍散失的注脚。晚年再嫁与诉讼，按宋律妻告夫须判徒刑二年，她仍决然起诉，折射宋代女性在婚姻中的真实处境。她的词由闺阁闲情转入家国之痛，以个人遭际记录时代，使婉约词获得前所未有的厚度。身后作品散佚，后人辑《漱玉词》传世，其人其词终成中国文学史上不可逾越的高峰。",
