      {
        heading: "三十万岁币 百年太平",
        paragraphs: [
          "曹利用抵达辽营后，辽方承天太后、圣宗亲自接见，坚持索还关南之地（后周世宗柴荣所取瀛、莫二州）。曹利用以「地不可归」婉拒，请以岁币代之。双方往返磋商数日，曹利用最终许以每年银十万两、绢二十万匹。回到澶州行宫复命时，真宗正在用膳，使内侍问所许几何，利用以三指加于面颊——真宗误以为是三百万，失声言「姑了事，亦可耳」，随即听说实止三十万，大喜过望，厚赏曹利用，和议遂定。",
          "景德二年（1005）正月，宋辽正式交换誓书。盟约约定：两朝约为兄弟之国，宋帝年长为兄，辽帝为弟；宋每岁输辽银十万两、绢二十万匹，「更不差使臣专往北朝」；双方各守现有疆界，不得越界侵扰，沿边城堡不得增筑；两朝逃人悉数遣返；于雄州、霸州、安肃军、广信军置榷场，互通贸易。宋廷随后在边境张贴榜文，晓谕军民。《续资治通鉴长编》载盟约文本：「每岁以绢二十万匹、银十万两，更不差使臣专往北朝。」",
          "澶渊之盟后，宋辽各自罢兵，边境烽烟熄灭。自景德元年至宣和四年（1122）宋金海上之盟，一百一十八年间，两朝虽偶有摩擦，再未爆发全面战争。雄州、霸州榷场商旅往来如织，互市之利岁入可观；宋朝以三十万岁币之费，换得北境安宁，得以全力发展经济与文化。然长期承平亦使宋军武备日渐松懈，河北禁军「寝而不讲」，为后来徽宗朝联金灭辽、靖康之祸埋下隐患。盟约本身，遂成后世议论千载的话题。"
        ]
      }
