    interpretation: "澶渊之盟的价值，历来见仁见智。以财政论，北宋真宗朝岁入约数千万贯，三十万岁币不过九牛之一毛，远不及河北驻军一年的军费；且岁币多经榷场流回宋境，宋朝以经济手段维持和平，实为以小博大之策。以政治论，两朝约为兄弟之国，皇帝互称兄弟，这在古代东亚国际关系中极为罕见，宋廷以「财货换和平」的方式，换取了百余年的休养生息。但其代价同样深远：盟约使宋廷上下安于现状，军队战斗力下降，战略上陷入消极防御。至徽宗朝，宋金海上之盟轻率撕毁盟约，辽亡而北宋亦亡，足见和平若不以实力为后盾，终难长久。澶渊之盟既是宋辽两朝理性妥协的典范，也是宋朝重文轻武国策的必然产物。",
