          "靖康元年（1126），金兵破汴京，二帝北狩，宋室南渡。士大夫追原祸本，多以王安石变法为北宋亡国之阶。《宋史》列蔡京以下于《奸臣传》，而论者谓其源流实肇于熙宁。宋高宗南渡之后，为开脱父兄之责，亦归罪新党。自是七百余年，王安石备遭责难，至明清犹被訾议；清代蔡上翔始为辩诬，近代梁启超作《王安石传》，叹为三代下求得一完人。誉之者比于近代国家主义之改革，毁之者斥为祸宋之首，誉毁之间，而变法本末俱在史册。"
