    interpretation: "王安石变法之深层逻辑，在于以国家权力直接介入财政、金融与军事，将汉唐以来藏于民间、归于豪强的利权收归朝廷。青苗、市易二法尤具近代财政金融之雏形：以官府为贷主、以信用为手段、以平准为职志，此即论者所称帝制时代最具近代色彩的改革尝试。然其根本困境在于：专制官僚体系既无有效监督，则良法易成弊政，抑配、催科、敛息层层加码，终至利归于上、怨归于下。且变法触动权贵利益，反对者既据道德高地，推行者益任用新进，新旧党争由政策分歧走向道德否定，元祐尽废、绍圣尽复，翻覆之间国本耗损，遂开靖康之局。要之，新法得失实为中国传统国家治理能力之一大试炼，其经验与教训，皆超出赵宋一朝之范围。",
