          "靖康元年（1126）正月，金东路军进抵汴京城下，攻城甚急，李纲率军民力战，金军不克。宋将姚平仲率步骑万人夜袭金营，因谋泄而败，钦宗益惧，罢李纲以谢金人。太学生陈东率都民数万人伏阙，群情激愤，击杀内侍数十人，钦宗不得已复李纲之职。既而宋金议和：宋割太原、中山、河间三镇，输金五百万两、银五千万两，金东路军遂北撤。然宋廷战和摇摆不定，钦宗既遣使割地，又密诏三镇固守不割，和议终成空文。西路军围太原二百五十余日，粮尽援绝，知府张孝纯城陷被执。",
          "八月，金太宗复命宗翰、宗望两路进兵，九月太原陷落，十月真定陷落，十一月初金军合围汴京。时城中断粮，援兵不至，钦宗罢李纲出知扬州，主战之臣尽去。闰十一月初，金军大举攻城，鹅车、火梯、云梯并进。钦宗不思整军御敌，反信术士郭京「六甲神兵」之法，令其开宣化门出击；郭京兵败遁走，金军乘隙登城。《宋史·钦宗本纪》载「闰月丙辰，京城陷」，其间死伤之惨、战况之烈，非笔墨所能尽。宋军犹巷战抵抗，宰相何栗率部死斗，终不能支。"
