    interpretation: "崖山之败，是南宋军事与战略积弊的总清算。自襄樊失守，长江上游不保，南宋已失战略纵深；行朝流亡闽粤，无后方、无补给，全凭水军孤悬海上。张世杰铁索连舟，虽可使船阵坚固、士卒无路可退，却放弃了水战赖以制胜的机动性，与汉末赤壁曹军之失如出一辙；且千余艘船中多为商舶民舟，战兵仅数万，家眷百工随行，一旦被围，饮水粮秣皆成死穴。张弘范围而不攻、断其汲道、以逸待劳，实为避其锋而攻其必救。后世论者或疑张世杰当弃崖山而走占城，然以宋军疲弊之师、海上漂泊之后勤，远遁亦未必可全。十万浮尸，多为随军家眷与百姓，并非尽为战殁，这一数字本身即是行朝举国播迁悲剧的注脚。至于「崖山之后无中国」之说，实为后世愤激之论：元朝一统后行汉法、修三史，中华制度与文脉并未断绝；而文天祥、陆秀夫所代表的忠义之气，反在明清以降成为民族精神的不竭泉源——宋虽亡，中国魂在。",
