    interpretation: "《资治通鉴》的深层价值，在于把「以史资政」的理念落实为一套可操作的史学方法。其丛目、长编、笔削三段工序，配合《考异》三十卷对史料歧异的精密辨析，开创了编纂学与考据学的新范式，后世修史多沿其法。就体裁而言，自《左传》之后编年体长期为纪传体所掩，《通鉴》一出，编年体重与纪传体分庭抗礼，故后人有「前后两司马」之说。其取材「善可为法、恶可为戒」，百余篇「臣光曰」借古议今，集中体现北宋士大夫以礼制名分立国的政治理想；也正因其资政宗旨，全书详于军国大事，略于文化与社会生活，不载屈原、陶渊明之属，司马光本人在熙宁党争中的立场亦不免影响史论取向。然其网罗宏富、体大思精，终使此书超越一朝一代之用，成为流播千年的帝王镜鉴。",
