          "西传之路，则以蒙古西征、丝路往来为孔道。元代驿路通达，波斯、阿拉伯商旅教士往来东西，印刷之术随之西渐。十三世纪末，波斯大不里士一带已见雕版印制纸牌、图像，欧洲亦于十四世纪出现木版印书，皆东方印刷西被之迹。至于活字，敦煌出土之回鹘文木活字，为其要证。欧洲金属活字之渊源，学者或溯之铸币、榨酒压印之器，多主独立发明之说；然东方活字早出四百年，其西传之迹与启发之功，亦未可轻忽。东西印刷，或因或创，要皆归于活字一途。",
