    interpretation: "活字印刷术之创制，非天纵之奇思，乃雕版极盛、需求飙涨之世，技艺自身演进之必然。毕昇之贡献，不在材质之贵，而在理念之变：化「整版」为「单字」，使文字成为可重复拼合之零件，实开近世印刷标准化、组合化之先声。然活字在中国未尝尽夺雕版之席，其故在于汉字字数繁多，排字、校字之费不赀；雕版一经刻成，可印千部而字画精整，士大夫宝重之。故活字之长在短印、急就，雕版之利在久藏、精刊，二者并行，各擅其场，与欧洲字母文字语境下活字独胜之局不同。毕昇布衣无传，其术赖沈括《梦溪笔谈》而存；一技之微，得与正史典章同垂不朽，此中国科技史之一大幸事。要之，活字印刷术继雕版而起，比古腾堡早四百年，为世界印刷史上又一次革命，其于人类文明，功在千秋。",
