          "入宋，理学先觉者首推周敦颐。敦颐字茂叔，道州营道（今湖南道县）人，生于真宗天禧元年（1017），历官分宁主簿、知南康军，著有《太极图说》《通书》。任南安军司理参军时，庆历六年（1046），大理寺丞程珦见而异之，遂命二子颢、颐师事之。敦颐之说，首言「无极而太极」，以「诚」为五常之本，将儒家伦理接于宇宙根源，道学之萌芽实始于此。同时有邵雍，字尧夫，共城（今河南辉县）人，生于大中祥符四年（1011），隐居洛阳，著《皇极经世书》二十卷，以象数推演天地终始之数，与二程比邻而居，程颢叹其学为内圣外王之道。",
          "张载字子厚，凤翔郿县（今陕西眉县）横渠镇人，生于真宗天禧四年（1020）。少喜谈兵，欲结客取洮西，见范仲淹，仲淹劝读《中庸》，遂折节向学，著《正蒙》《西铭》。其言曰：「为天地立心，为生民立命，为往圣继绝学，为万世开太平。」见《宋史·张载传》，道学立教之宏愿尽此四语。熙宁十年（1077）卒于临潼。程颢（1032—1085）字伯淳，号明道，嘉祐二年（1057）进士；程颐（1033—1107）字正叔，号伊川，以布衣讲学洛阳。元祐元年（1086）司马光荐颐为崇政殿说书。颢尝言：「吾学虽有所受，天理二字却是自家体贴出来。」天理既立，道学之名始彰。"
