          "朱熹以毕生之力遍注群经，尤留心于人伦日用之书。淳熙九年（1182）始并刊《大学章句》《中庸章句》《论语集注》《孟子集注》，至淳熙十六年（1189）序定，合称《四书章句集注》，凡四十二卷。其学以「理」为宇宙本体，理在气先，理一分殊；论性分天命之性与气质之性，使性善之说与恶之来源各有安顿；论工夫则主居敬穷理、格物致知，存天理而去人欲。又取周敦颐、二程、张载四子之言，与吕祖谦合编《近思录》十四卷，淳熙二年（1175）成于建阳，为后学入道之门。门人辑问答之语为《朱子语类》一百四十卷，理气心性、读书治事，无不备载，蔚为大观。",
          "淳熙二年（1175）六月，吕祖谦约朱熹与陆九龄、陆九渊兄弟会于信州（今江西上饶）鹅湖寺，即鹅湖之会。九渊字子静，抚州金溪人，生于绍兴九年（1139），乾道八年（1172）进士，号象山。三日之间，朱主格物致知、泛观博览而后归约，陆主发明本心、先立其大，辩难不决。九渊讥朱为「支离事业」，朱亦讥陆「太简」，至有「禅学」之疑，终不复合，朱陆之争自此判为两派。淳熙八年（1181）朱熹知南康军，邀九渊白鹿洞讲「君子喻于义」章，朱以为切中学者隐微深锢之病。九渊后知荆门军（1191—1192），淳熙十六年（1189）卒，朱闻之率门人哭祭，二家虽异，敬之如故。"
