    interpretation: "伯颜下临安，是元朝统一战争中决定性的一役。其成功，首在战略：元军先取襄樊，控汉水入长江之上游，再顺流东下，以丁家洲、焦山两战歼灭宋军主力与水师，使南宋「以江立国」的防御体系彻底瓦解；继而分兵三路，会围临安，断其退路。次在军政并用：忽必烈以曹彬期伯颜，严戢杀掠，入临安而封府库、收图籍、护宗庙，市不易肆，以此安抚江南士民，瓦解抵抗意志。南宋之亡，根在内政：度宗早逝，幼帝在位，谢道清垂帘而实权落于贾似道之手，边报壅蔽，勤王之诏虽下而义军无统。文天祥以书生散家财、聚义兵，忠义足以动天地，终不能挽狂澜于既倒。宋室再无南渡之机，与北宋之亡遥遥相对，后人以「靖康」与「德祐」并称，视为亡国之痛的两次重演。此役之后，元朝完成大一统，南北混一，其影响远超一代之兴亡。",
