          "六月，金军悉数北撤，退出淮南州军，西线亦归还大散关。宋廷遣使奉誓书如金，金亦遣使报命，自开禧二年五月以来三载兵戈，至是暂息。王柟以使事还朝，宋廷录其劳。然岁币银绢各三十万两匹，较绍兴旧约各二十五万两匹犹重，犒军银三百万两又出于格外；此约之成，实以兵败之后俯首以就金人条件，非复隆兴之际彼此相持之局，士庶虽庆息兵，而国用已屈。",
