          "金虽战胜，所得亦仅韩侂胄之首与增币之利。泰和年间连年用兵，士马死于淮南、川陕者以万计，府库殚竭，山东、河北群盗蜂起。泰和八年（1208）冬，金章宗完颜璟病逝，无嗣，叔父卫王完颜永济继位，后追贬卫绍王。蒙古已在漠北立国，铁木真于1206年称成吉思汗，数扰金之北边。金之精锐半耗于南，而北防空虚，和议虽成，金廷欲专力北防，而力已不逮，祸胎已伏。",
