          "为北伐造势，宋廷先扬岳飞而抑秦桧：嘉泰四年（1204），宁宗追封岳飞为鄂王，以彰忠义之节，为北伐造势；开禧二年（1206）四月，又追夺秦桧申王之爵，改谥「缪丑」，将主和之臣钉于耻辱柱上。开禧元年（1205）起，宋廷于两淮、京湖、四川沿边增兵积粮，遣人潜入中原联络忠义，复起辛弃疾知镇江府。辛弃疾登北固亭，北望山河，有「凭谁问：廉颇老矣，尚能饭否」之叹。叶适时任权吏部侍郎，力谏不可轻启战端，不报。战端遂不可免。"
