          "符离之溃后，金朝以世宗完颜雍之命，调仆散忠义为都元帅，开府南京（今河南开封），总统南面军事；以纥石烈志宁为左副元帅，驻军河南，节节进逼两淮。隆兴元年（1163）八月，张浚病逝于都督府任上，享年六十八岁，孝宗痛悼辍朝，赠太保，谥忠献。张浚既殁，主战派失其领袖。左仆射汤思退乘势秉政，引王之望、龙大渊等为腹心，力主尽撤两淮戍备，遣使赴金营请和，甚至撤海州、泗州戍兵，弃淮北于不顾。",
          "是年秋冬，金军大举渡淮南下。纥石烈志宁自清河口（今江苏淮阴西）渡淮，破楚州，陷濠州、滁州，游骑至扬州、六合，江东大震。宋将魏胜率忠义兵苦战于淮阴，粮尽援绝，力战死之，朝野闻而悲之。然金军顿兵两淮，师老兵疲，粮运不继；金世宗新即位，契丹移剌窝斡之乱方平，国用未充，本无灭宋之力。双方皆已无力再战，和议遂为唯一出路。战和之争、胜败之数，共同把孝宗推向了议和之局。",
          "隆兴二年（1164）初，孝宗遣卢仲贤使金，金帅仆散忠义授以书，索四事：宋称侄国、岁币、归附之人、疆界如旧。卢仲贤还朝，孝宗初欲拒之。八月，再遣王之望、龙大渊赴金，朝议纷纭。十一月，金军再破楚州，宋廷震动，孝宗乃决意从和议。十二月，以礼部尚书魏杞为通问使赴金，金世宗览书，遂许和。条款由仆散忠义、纥石烈志宁与宋使往复磋商，最后定于隆兴二年十二月。"
