          "自绍兴和议以来，宋帝向金主奉表称臣，国书用表，受金主册封；至是改为侄国，国书称「侄宋皇帝」，金书称「叔大金皇帝」，正旦、生辰互遣使贺，礼数略平。金世宗完颜雍（1123年生）长孝宗赵昚（1127年生）四岁，叔侄之称于年齿亦合。岁贡改岁币，虽仍是资财输纳，却洗去「贡」字的臣属含义。孝宗虽未能雪靖康之耻、复中原之土，然以败军之后争得此数事，已非绍兴和议之比。宋金由君臣之国改为叔侄之国，宋帝不再对金称臣。",
          "隆兴二年十二月，金都元帅仆散忠义遣使赍和书至，孝宗许之。次年（1165）正月，金世宗遣使以和议来告；宋改元乾道，以示更化更新，和议正式换约。此后每年春季，宋于泗州交割岁币，金于泗州、宋于盱眙各有榷场通商。岁币四十万两匹之数，较绍兴减十万，以南宋东南财赋之力尚可负担，不似后世开禧增币之重。宋金自隆兴二年罢兵，迄开禧二年（1206）韩侂胄北伐，维持近四十年和平，南北对峙格局基本定型。"
