          "危急之际，宋廷起用孟珙经营川蜀。嘉熙三年（1239），孟珙出任四川宣抚使兼知夔州，于归州、峡州一带布防，阻断蒙古军顺江东下的通道，稳定了三峡防线。淳祐二年（1242），宋理宗以余玠为兵部侍郎、四川安抚制置使兼知重庆府，入蜀主持全局。余玠到任后整顿军政，惩办贪懦，又筑招贤馆于重庆府治之左，广纳贤才。布衣冉琎、冉璞兄弟前来献策，主张徙合州城于钓鱼山，以为蜀之要害所在。",
          "余玠采纳其议，淳祐三年（1243）开始修筑钓鱼城，随后又筑云顶、青居、大获、苦竹等十余座山城，依山制水，互为犄角，构成川蜀山城防御体系。此后蒙古骑兵虽野战无敌，却顿挫于山城之下。淳祐十一年（1251），余玠出师北伐汉中，虽未全功，西线局势已趋稳定。山城体系使蒙古在蜀中每前进一步都付出巨大代价，南宋西线由此支撑二十余年。"
