          "开庆元年（1259）二月起，蒙哥督数万大军围攻钓鱼城。守将王坚、副将张珏率军民凭险坚守，以滚木、巨石、火器击退蒙古军一次又一次进攻。蒙古军屯兵坚城之下，正值盛夏暑湿，疾疫流行，死者甚众。自二月至七月，攻围数月不能下。七月，蒙哥死于钓鱼山下，关于其死因，史书或云染疾，或云中飞石，至今未有定论。蒙哥一死，蒙古全军解围北还。",
          "蒙哥之死使蒙古的灭宋全局骤然瓦解。正在围攻鄂州的忽必烈闻讯，为争夺汗位仓促撤兵北返，兀良合台亦自南方撤军。蒙古宗王各军纷纷回师漠北，忽必烈与阿里不哥随即爆发长达四年的汗位之争。南宋抓住喘息之机暂得保全，然贾似道以鄂州之功擅权，朝政愈发败坏。战争虽暂时转入低潮，南宋的腐朽也已病入膏肓。"
