          "庆历四年（1044）六月，朋党之议起于朝。先是元昊已奉表请和，而夏竦之党造为流言，谓范仲淹等交结朋党、专擅朝政。仁宗御迩英阁，以「小人朋党」为问，范仲淹对曰：「自古邪正在朝，未尝不各为一党，在陛下辨之耳。」欧阳修亦上《朋党论》，以为君子以同道为朋、小人以同利为朋，人主但当退小人之伪朋、进君子之真朋。然仁宗疑终不释。同月，以夏宋议和而边防未撤，遣范仲淹宣抚陕西、河东，富弼宣抚河北，名为出抚，实出之以避谤。",
          "十一月，进奏院狱起。监进奏院苏舜钦为杜衍之婿，与右正言王益柔等宴集，召妓娱客，以鬻故纸之钱充酬。王拱辰等素憾杜衍、范党，遂劾其监主自盗、肆为狂言。仁宗怒，下开封府鞫治，苏舜钦除名勒停，王益柔贬黜，同宴者十余人皆坐贬。此事本一细故，而王拱辰等借以倾陷杜衍、范仲淹，时论冤之。台谏交章营救，仁宗不听。朝中正人不安其位，新政根基自此动摇。"
