          "新政既废，石介以忧卒于家，夏竦犹衔其怨，请发石介之棺验视，谓其诈死北走契丹，虽事未果行，而株连恐吓之状可见。范仲淹既去，士大夫犹慕其风节。史臣论曰：「每感激论天下事，奋不顾身，一时士大夫矫厉尚风节，自仲淹倡之。」庆历六年（1046）九月，范仲淹在邓州应友人滕宗谅之请，作《岳阳楼记》，有先天下之忧而忧、后天下之乐而乐之语，天下传诵，庆历精神赖以不坠。",
