    interpretation: "庆历新政之败，非败于法之不善，而败于势之未可。仁宗之世，承平八十余年，冗官、冗兵、冗费盘根错节，皆祖宗防弊之政所酿成。范仲淹以整饬吏治为先，磨勘、恩荫之制一变，则百官禄位可危；按察之使一出，则庸吏私利可危。故攻之者不曰法弊，而曰朋党——朋党之罪，人主之所深忌也。仁宗始用之而终疑之，亦祖宗家法使然：宋惩唐末五代之乱，设枢密、三司以分宰相之权，置台谏以制执政之柄，本不容一派专擅。新政诸贤恃仁宗之信，锐意更张，而不知结主心、安反侧，一旦谤言交集，进退遂失所据。然其风节所及，激起一代士大夫之主体意识，故虽败而其志不灭；二十余年后王安石以熙宁变法继之而起，虽局面迥异，其以天下为己任之精神，实自庆历一脉相承。",
