          "朱熹既落职罢祠，退居建阳考亭，杜门著书，不问外事。其论著不辍，于《书》《诗》《礼》诸经皆有训说，又成《楚辞集注》八卷，借屈原放逐之辞，寓己身之幽忧。门人蔡元定编管道州，朱熹追饯之于建阳萧寺，相与对饮，悲歌而别，门人皆泣下。庆元四年（1198年），蔡元定卒于道州贬所，朱熹闻之，痛悼不已。其一生出处，《宋史》本传论之曰：「熹登第五十年，仕于外者仅九考，立朝才四十日。」登第之久，立朝之暂，著书之勤，俱见于此数语，读之令人低回不已。",
          "庆元六年（1200年）三月，朱熹疾作，犹与门人黄榦、蔡沈等讲论不辍。是月甲子，卒于建阳考亭，年七十一。门人会葬者近千人，虽党禁方严，四方学者不远千里而至，送葬之车，填塞道路，有司不能禁。辛弃疾闻讣，为文以祭之，其辞有「所不朽者，垂万世名；孰谓公死，凛凛犹生」之语，悲壮苍凉，见者动容。葬于建阳九峰山之大林谷。一代大儒，终于党禁未解之日，天下闻之，莫不流涕，而其学之传，正自此益广。"
