          "开禧二年（1206年），韩侂胄兴开禧北伐，兵败。开禧三年（1207年）十一月，礼部侍郎史弥远与皇后杨氏定谋，密谕权主管殿前司公事夏震，击杀韩侂胄于玉津园。《宋史·韩侂胄传》论其始终，有「侂胄用事十四年，威行宫省，权震天下」之语。韩侂胄既死，函首送金，和议乃成。朝廷尽复党人官秩，雪赵汝愚之冤，追复其官。韩侂胄死后，党人尽复，党禁之祸，至此始尽除，而南宋国势，已因此内耗而渐趋颓敝。",
