    interpretation: "庆元党禁之祸，表面视之，为学术之争，实则权位之争。赵汝愚、韩侂胄皆为定策功臣，一以宗室之臣拜相，一以外戚之亲窃权，势不两立，而朱熹一派适居其间。韩侂胄欲逐赵汝愚，患其党众，乃以「伪学」之名罗织之，使政敌尽为一党，而后可一举网尽，其法与元祐党籍碑如出一辙，而株连之广、禁锢之严，视元祐更甚。然学术可禁于一时，不可绝于久远。韩侂胄用事十四年，威行宫省，权震天下，终函首以和；朱熹虽困顿以死，其后学转盛。嘉定赐谥，淳祐从祀，理学遂由民间之学进为官方正统。庆元党禁是宋代以学术治罪的党争高峰，亦埋下理学由民间之学转为官方正统的伏笔，其禁之酷，适为其学之传也。",
