    interpretation: "绍兴和议之订立，非单纯屈辱求和，实为高宗赵构与宰相秦桧以皇权稳固为最高目标的政治交易。对外，以称臣、纳贡、割地换取金朝停战与帝位承认；对内，借和议之名收三大将兵权，终结家军之局，重建枢密院统兵之制。岳飞之死，实为这笔交易不可避免的代价：其人望、战功与主战立场，皆为和议之障碍。短期观之，和议带来二十余年和平，江南经济文化得以持续繁荣，岁币五十万两匹亦远低于战争开支；长远观之，君臣名分既定，南宋法统屈居金朝之下，武将遭抑，恢复无望，偏安格局由是固化。后世论之，或责高宗怯懦、秦桧奸佞，或谓势所必然、两害相权取其轻。要之，和议乃南宋在军事均势之下以名分换生存之选择，其代价由岳飞等将领与忠义之气承担，利钝得失，至今仍为读史者深慨。",
