          "《宋史·章惇传》载：「惇为相，报复仇怨，小大之臣，无一得免者。」其治元祐党也，置看详诉理局、编类章疏所，专以罗织为务。绍圣三年，同文馆狱起，事连刘挚、梁焘、王岩叟，锻炼成案；凡元祐臣僚章奏，悉编类定罪。绍圣四年，立元祐党人籍，姓名著于州县，子弟不得与科考，不得与宗室通婚。株连之广，北宋百年所未有。",
          "章惇等甚至欲尽诛元祐旧臣，遣使至岭南，将害刘挚、梁焘等，会帝崩乃止。元符三年（1100），谪臣多死于贬所：吕大防卒于虔州，刘挚、梁焘皆殁于岭南。党争至此，已非政见之争，乃生死之仇。旧党既败，新党复分：章惇与曾布交恶，蔡京、蔡卞兄弟亦各立门户。朝堂之上，彼此倾轧不休，国事遂不可为。元符末年，哲宗疾甚，皇位未定，危机四伏，而党人犹争不置。"
