    interpretation: "宋江起义在北宋末年群雄中规模并不显赫，然其影响之深远，实出于文学而非史实。就史实而言，宋江以三十六人起于河朔，转掠京东十郡，历时约三年而败于海州，其事当与方腊起义合观：一北一南，同起于宣和间，皆为徽宗朝苛政——花石纲之搜刮、冗官冗兵之积弊、联金灭辽之糜费——所激成。侯蒙以盗攻盗之策、张叔夜焚舟伏兵之举，折射出北宋官军数万不能制三十六人之腐朽军政。宋江就擒后六年，金兵南下，靖康之变作，北宋遂亡，河朔京东之地首当其冲。而宋江其人其事，经南宋说话、元杂剧层层累积，终成《水浒传》百回大书，梁山聚义、官逼民反之叙事，深刻塑造了中国民间对乱世英雄之想象。一部宋江起义之流传史，实为史实消解、文学重构之典范。",
