      {
        heading: "陈家谷殉节",
        paragraphs: [
          "七月，辽将耶律斜轸反攻西路，破寰州，兵锋直指朔州。太宗诏潘美、杨业掩护云、应、寰、朔四州之民内迁。时辽军十万众云集，杨业审时度势，主张避其锋锐，自大石路（今山西应县东南）出击，护军民从容南撤。然随军监军王侁与都监刘文裕不谙军机，讥杨业畏敌怯战，欲逼其正面交锋。杨业性刚烈，知必败而不得已请行，临行泣谓潘美曰：「此去必死，愿明公设伏于陈家谷口，相机接应。」潘美许之，遂与王侁引兵屯于谷口。",
          "杨业率麾下数千人自朔州南撤，辽军追兵数万，踵趾相及，转战数十里，未能脱身。原来潘美、王侁闻杨业兵败，以为全军皆没，竟弃谷口引兵退去，伏兵遂空。据《宋史·杨业传》载：「业力战，自午至暮，果至陈家谷口，望见无人，即拊膺大恸，再率帐下士力战，身被数十创，士卒死伤殆尽，业犹手刃数十百人，马重伤不能进，遂为契丹所擒。」其子延玉亦战死于阵，麾下士卒无一生还者。",
          "被擒之后，辽将欲降之，杨业不屈，长叹曰：「陛下遇我甚厚，期捍边破贼以报恩，今为奸臣所嫉，逼令致死，致王师败绩，何面目求活哉！」乃绝食三日而死，年六十（《宋史·杨业传》）。杨业生前威震契丹，辽人畏之，号为「杨无敌」。太宗闻之痛惜，下诏褒恤，赠杨业太尉、大同军节度使，赐其家布帛千匹、粟千石，录其子延朗（后改名延昭）等五人为官；潘美坐削三任，王侁除名配隶金州，刘文裕除名配隶登州。然将星已陨，天下闻之，皆为流涕。"
        ]
      },
      {
        heading: "转攻为守",
        paragraphs: [
          "辽军乘北伐新败，大举南伐。是年冬，耶律休哥率铁骑长驱南下，与宋军瀛州兵马都部署刘廷让大战于君子馆（今河北河间一带）。刘廷让以麾下精兵悉付都监李继隆为后援，李继隆见辽军势大，不战而退保乐寿，刘廷让孤立无援，孤军奋战，全军覆没，仅以身免。君子馆一役，死者数万，河北宋军精锐尽丧，州县望风而溃，辽骑深入邢州、深州，大掠而去，所过焚掠一空。太宗急发京师禁军赴援，分守要害，辽军始退。",
          "自此，太宗彻底放弃武力收复燕云之念，转取守势。自高梁河、岐沟关两败，太宗深知宋军野战非辽军之敌，遂以固守为长策。宋廷于河北广开屯田，疏浚塘泊，自保州东至泥姑海口，屈曲九百里，筑堤蓄水，连绵不绝，以限辽骑驰突；又沿边择要置寨戍兵，坚壁清野，以静制敌；其后知沧州何承矩等历岁营缮，塘泊益深广，又募乡兵、义军分番戍守，以省馈运之劳。朝中主战之议渐息，守内虚外之策渐成国是，雍熙而后，宋廷再无倾国之师出塞，凡有边事，唯以防守为务。",
          "雍熙北伐是宋辽关系的分水岭。此役之后，北宋对辽由战略进攻转为战略防御，收复燕云十六州的宏图就此搁置，直至景德元年（1004）澶渊之盟，宋辽约为兄弟之国，以白沟河为界，宋岁输辽银十万两、绢二十万匹，双方百年无大战。辽国经此一战，国势益盛，萧太后临朝二十余年，《辽史》称其「明达治道，闻善必从」。至宣和间宋联金灭辽，虽得燕山空城，未几金兵南下，汴京陷落，燕云之得旋失，北宋亦随之而亡，燕云之失终成赵宋君臣世代未解之地缘心结。"
        ]
      }
