    interpretation: "雍熙北伐之败，非独将帅之失，实有深层制度与战略之因。宋初惩五代藩镇之祸，将不专兵、兵不识将，阵图授受，将帅临阵多禀庙算，难以随机应变；行军依赖步卒与民夫转运，而辽军铁骑来去如风，粮道动辄被断，此曹彬进退失据的根本原因。太宗以天子遥制千里之外，进退赏罚之权尽出中枢；监军王侁辈以朝官临制宿将，杨业之死正是这一痼疾的缩影。此役之后，宋廷承认骑兵不如辽军之现实，转以塘泊、屯田为固，守内虚外，边防战略彻底改观。而辽廷经此一战，军威大振，萧太后威权日固，宋辽力量对比由此逆转，终成澶渊对峙百年之局。",
