      {
        heading: "绍圣绍述，国势内耗",
        paragraphs: [
          "元祐九年（1094）四月，哲宗用杨畏之言，诏改元绍圣，以「绍述」神宗之政为号。章惇自苏州召还，拜尚书左仆射兼门下侍郎，专执国政；曾布、李清臣、许将、蔡卞等次第还朝，新党尽复其位。未几，复免役、青苗、保甲、市易诸法，熙丰旧章次第复行，元祐所改，一切反之而还。一代之制，废于一令，复于一令，法度随人事为翻覆，而纪纲遂不可问矣。",
          "绍述既行，报复相寻。苏轼贬知英州，未至，再责宁远军节度副使、惠州安置；苏辙责授化州别驾、循州安置；范纯仁、刘挚、梁焘、刘安世等元祐旧臣，无论存殁，皆远窜岭表。绍圣四年（1097），追夺司马光、吕公著所赠官并谥号；章惇、蔡卞又纂集元祐臣僚章奏，罗织党祸，株连几数百人。死者毁其赠恤，生者加以贬谪，自车盖亭以来之倾轧，至此而极。",
          "元符三年（1100）正月，哲宗崩，无嗣，端王赵佶即位，是为徽宗。蔡京以新党余绪还朝，崇宁元年（1102）籍定元祐党人，立碑端礼门外，刻司马光、文彦博、苏轼、苏辙、程颐等三百九人姓名，谓之「奸党」，禁其子孙仕宦，不得至京师。自此党祸连绵，毒流四海；后二十五年，金人入汴，徽宗父子北狩，北宋遂亡。元祐更化以拨乱反正始，以党亡国终，良可叹也。"
        ]
      }
