    interpretation: "元祐更化之失，不在「更化」本身，而在其方式与逻辑。司马光、吕公著皆一代名臣，其意本欲恤民困、复旧章；然一年之内尽罢诸法，不问利钝，一反熙丰，其立法之骤，比之王安石有过之。更深一层，高太后以祖母临朝、以母改子，权柄虽正，于哲宗则如芒在背——天下皆知有宣仁，而不知有皇帝。哲宗亲政后绍述，并非尽为新法之利，实为十三年受制帘前、压抑已极的反激。新旧两党，初为政见之异，自车盖亭诗案、洛蜀朔三党之争后，渐成君子小人之辨、恩怨死生之局：台谏本以言责纠弊，至此沦为党同伐异的工具。北宋之亡，论者每咎王安石变法，实则变法未必亡国，而由变法、更化、绍述、党人碑一脉相承的意气内耗，方是耗尽国本的根源。",
