    interpretation: "岳飞北伐的失败，非战之罪，乃政治之败。高宗赵构之所以力主和议，一则惧金，二则惧将。迎回徽、钦二帝，则自身皇位不保；岳飞功高盖主，则武将难以驾驭。在帝王眼中，内部的威胁甚于外敌。秦桧揣摩上意，以「莫须有」之罪陷害岳飞，实为高宗意志的执行者。岳飞之悲剧，折射出南宋政权的核心矛盾：军事上的进攻需求与政治上的求安需求不可调和。岳家军的战斗力越强，高宗的疑忌越深。南渡以来，武将势力膨胀，建炎年间苗傅、刘正彦之变，更令高宗对武将深怀戒心。岳飞「尽忠报国」之志，终不敌帝王之家天下之私。此后南宋偏安江南一百五十余年，虽有隆兴、开禧两次北伐，终未能恢复中原。",
