    interpretation: "保甲制的深层逻辑，在于以乡村自警自治替代国家养兵，以连坐互保强化基层控制。王安石的设想，是让农民在农闲时接受军事训练，逐步顶替募兵，从而把养兵的财政包袱转嫁于民间。但这一设计一开始就低估了募兵制与宋代社会结构的适配度。宋代不抑兼并，主户、客户贫富分化，保长、都保正由物力高的主户充当，他们与胥吏、豪强合流，保甲很容易变成科扰百姓的工具。保丁教阅误农、上番贴费，使农民负担加重；而禁军并未裁撤，军费有增无减，民兵代募兵的目标自然落空。元祐以后，保甲的军事功能被罢去，只留下治安与互保连坐，反而证明它在乡村治理上的价值，后世王朝沿袭的正是这一层。可以说，保甲制作为军制改革是失败的，作为治安制度却是成功的。",
