    interpretation: "毕昇活字术之本质，在将整版死刻分解为单字组合，使印刷工艺标准化、可重组，与雕版固定整版形成根本分野。然汉字数量庞大，《广韵》收字二万六千余，字盘管理、拣字排版皆需熟练技工，故泥活字虽巧，在古代中国未全面取代雕版，二者长期并行：雕版利于书法美感与图版镌刻，活字之利在部头大、印数多之书。其历史地位不在即时之产业颠覆，而在开创信息复制可拆解、可重组的技术路线，为木活字、铜活字乃至金属活字之祖，泽被东西；其事又见宋代工匠技艺与士大夫记述相合，始得传世，足证技术之存亡，亦系于记载与传承。",
