    interpretation: "范仲淹一生，历真宗、仁宗两朝，其进退成败皆与北宋中期之忧患相终始。论其事功，西北数年，以坚壁清野、筑城屯田之策遏元昊方张之师，使宋夏得成和议，关中免于沦没；其条陈十事虽旋行旋罢，然其所指冗官、冗兵、冗费之弊，历仁宗、英宗至神宗而愈甚，二十余年后王安石变法，实承其绪而张大之。论其风节，则《宋史》所谓「每感激论天下事，奋不顾身，一时士大夫矫厉尚风节，自仲淹倡之」。经晏殊荐引、富弼辅翼，宋代士大夫以天下为己任之风气实自仲淹启之；而义庄赡族、书院课士，又为地方公益与儒学复兴开先路。至于「先忧后乐」一语，遂为千古士人立身处世之标杆，非徒文章之美而已。",
