      {
        heading: "寒俊并进，文官政治",
        paragraphs: [
          "自此布衣孤寒得与势家子弟同场竞艺，科场取士唯程文是凭。每榜进士，多起于畎亩寒素，如范仲淹少年断齑画粥，后登大第；欧阳修家贫，以荻画地学书，终为文坛宗主。孤寒一旦登第，天子赐宴琼林，荣宠归于考试，而非门第、权贵的私恩。故宋代士大夫，不以门第自高，而以科名、文章自重；登第者感激天子与制度，非感激某位主司之私恩。恩门、门生之习渐绝，座主、门生之党亦随之消弭，此于抑制权贵、澄清吏治，关系甚大。",
          "宋代文官政治，由此奠定制度根基。选官不凭借着门第、姻亲、藩镇，而归于考试一途；权力来源既在天子与制度，士大夫遂以天下为己任，与天子共治天下。科举既为正途，宰相、侍从、台谏之臣，十九皆由科场进身；武将、外戚、宦官之途，皆不得干预大政。士大夫以进退出处，论列天下是非，庙堂之上，议论风生，君臣共治，实赖科举取士之公。糊名誊录虽为防弊之具，其效乃及于国家治体：取士公则人心服，人心服则士大夫乐于为用。",
          "元明清科举弥封、誊录之法，亦皆由此沿袭。元仁宗皇庆二年（1313）恢复科举，乡试、会试皆行弥封、誊录。明代乡会试设弥封所、誊录所，置封弥官、誊录官、对读官，程序一如宋制；清代因之，弥封、誊录、对读、收掌、受卷，各有专官，立法益密。直至清光绪三十一年（1905）废除科举，此制始随科举而废。自景德四年（1007）至光绪三十一年，糊名誊录作为考试防弊与程文取士的核心设计，行用近九百年，实为中国科举制度史上影响最为深远的技术性创设。"
        ]
      }
