    interpretation: "糊名誊录之制，本质上是以技术手段把人的因素从评卷中剥离出来。唐五代取士，主司先知其人，后阅其文，声誉、门第、关节皆得预其议；糊名则去其名，誊录则去其迹，锁宿则断其交，对读则防其伪，考官所见，唯朱卷与程文而已。取士标准由人转向制度，由荐举式的声誉转向考试式的客观比对，此即程序正义之制度化。其局限亦显：不能防代笔之弊，不能定文风高下之争，且程文取士，士子务为文辞，亦有流弊；然较之公荐行卷、势家垄断，已是制度之大进。中国科举史上，第一次以完整技术链条实现考官与举子的信息隔绝，使寒俊与势家同场竞艺，宋代文官政治由此奠基，元明清弥封誊录之法沿袭不改，其制度生命近九百年。",
