    interpretation: "《梦溪笔谈》之难能，在于它诞生于一个并不以「科学」为独立事业的时代。中国传统知识体系以经史为本，百工技艺视为贱工末业，不登大雅之堂；沈括以进士出身、朝廷达官之身份，而肯俯记工匠之术、田夫之言、药工之业，且以目验实证为判断依据，此其超出同时代人处。其方法——观测极星、磨磁试针、推论山川成因、详记活字工艺——已具实证思维之雏形。然其学问终依附于笔记体裁与士大夫之博物传统，未能发展出独立的知识门类与传承建制，神秘内容亦混杂其中，此为时代之限。要之，是书既是中国古代科学技术之总结性记录，亦是观察北宋社会、政治、制度与士人精神之窗口，其价值历千年而常新。",
