        paragraphs: [
          "崇宁三年（1104），宋徽宗赵佶召米芾为书画学博士。徽宗雅好书画，扩充翰林图画院，编纂《宣和书谱》《宣和画谱》，米芾入侍禁中，得以遍阅内府所藏，参与鉴定赏鉴。相传徽宗曾赐御砚，米芾捧砚叩谢，墨汁染满袍袖而不顾，其爱砚如此。在书画学博士任上，他品第古今，论讲笔法，鉴裁之精，一时无两。崇宁五年（1106）前后，擢礼部员外郎，因官礼部，世称「米南宫」，然未几即出知外州。",
          "米芾性情疏狂，不能与世俯仰，《宋史》本传论曰「不能与世俯仰，故仕数困踬」。其拜石一事尤传为千古佳话：知无为军时，州有巨石，状奇丑，米芾见之大喜曰「此足以当吾拜」，遂具衣冠拜之，呼之为兄，「米颠」之名由此传遍士林。又传其知涟水军时，日日玩石，不理郡政，按察使杨杰前来规劝，米芾自袖中取奇石示之，杨杰见之亦为之倾倒。其痴癖之深，乃至以诙谐自污以远祸，实则于怪石之中寄托了不随流俗的孤高襟怀。",
          "大观元年（1107），米芾出知淮阳军，未几卒于任所，年五十七，归葬润州。他历仕神宗、哲宗、徽宗三朝，所至以书画名世，而官秩不过州县、郎署。徽宗朝虽蒙简拔，终因性不容俗，未能久居清要。其殁后，长子米友仁承其家学，南渡后亦以书画供奉内廷，父子并称「大小米」，米氏家声由是不坠。其所藏晋唐名迹、所著书画诸史，多为后世考求古法所凭依。"
        ]
