      {
        heading: "米点皴开米家山水",
        paragraphs: [
          "米芾于画亦有创格。他不取唐人钩斫敷色之工，而取法董源、巨然江南山水，以水墨点染写云山雨景，创「米点皴」，世称「米家山水」。其画迹传世稀少，真迹已难确指，画史所载《春山瑞松图》及《珊瑚帖》中随笔写画之迹，犹可想见其意趣。他以错落落茄点表现江南烟雨迷蒙之景，不求形似，但求意趣，正合北宋文人画萧散简远之追求，亦与其卑唐崇晋、不蹈前人轨辙的艺术主张一脉相承。",
          "米家山水经其子米友仁发扬光大。米友仁画《潇湘奇观图》《云山墨戏图》，纯以墨点写云山，世称「小米」，与父并称「大小米」。南宋以降，米氏云山成为文人画一大宗脉，元代高克恭、方从义皆取法于此，明代董其昌标榜南北宗、以南宗文人画为正统，更将米氏父子列为南宗关键人物。米芾创「米点皴」开米家山水一派之壮举，遂由一家之体式化为千古之典范，沾溉后世书画极深，其影响所及，远超宋世。",
          "综述其一生：书法博采晋唐，尤得王献之笔意，与苏轼、黄庭坚、蔡襄并称「宋四家」；山水画创「米点皴」，开米家山水一派；又嗜奇石、拜石称兄，世称「米颠」。所遗《苕溪诗帖》《蜀素帖》《珊瑚帖》《拜中岳命帖》《研山铭》等，皆为传世剧迹；《书史》《画史》诸作，至今仍为鉴赏之准绳。其人仕途偃蹇而艺术不朽，人以「米颠」笑之，亦以「米颠」传之；千载之下，犹想见其拜石呼兄之狂态、八面出锋之笔意。"
        ]
      }
