    interpretation: "米芾一生，恰在北宋艺术由唐法转向宋意之枢纽上。他以「集古字」自嘲，实则走的是由临摹入、由化出离的正路：遍观晋唐名迹，精审其用笔源流，再以自家性情熔铸之，故能「沉着飞翥」，不蹈前人轨辙。其「米颠」之名，世人多笑其狂，而《宋史》「不能与世俯仰，故仕数困踬」一语实已道破根由：正是这种不随流俗的痴癖，成全了其艺术的极致，也注定了其仕途的困顿。书列宋四家，画开米家山水，著作为后世鉴赏之准绳——米芾以一州县下僚之身，而在千年书画史上占据不朽之位，正可见宋代右文之下，艺术与人格得以独立于功名之外的深层逻辑。",
