    interpretation: "欧阳修的历史地位，须从三条线索同时看。文学上，他以嘉祐二年贡举为杠杆，用取士标准重塑文风，使宋代散文走上平易自然、文道合一之路，唐宋八大家中宋占其六，苏洵、苏轼、苏辙、曾巩、王安石无一不经其赏识奖引，堪称宋文一代宗匠。史学上，《新五代史》为二十四史中唯一私修正史，寓褒贬于纪传；《新唐书》恢复表志，弥补《旧唐书》疏漏；《集古录》开金石学之门，《六一诗话》创诗话之体，著述之勤遍及四部。政治上，他三朝为官，庆历直言、濮议执礼、熙宁守正，虽屡遭诬陷贬黜而风节不改。其局限亦明：以科举好尚定文章高下，不无门户之见；濮议之争以宰执压台谏，开后世政争之隙。然观其一生，以道自任、以文行远、以史立训，正是宋代士大夫主体意识成型期的典范人物。",
