          "三大将释兵之后，岳飞独不肯附和议，遂为秦桧必去之人。绍兴十一年六月，秦桧嗾右谏议大夫万俟卨、侍御史罗汝楫连章弹劾岳飞，罪状皆捕风捉影：诬其逗留淮西、援兵不进、动摇国是。岳飞上章自辩乞罢，出居江州私第。九月，又使人诬告岳飞部将张宪与其子岳云暗中交通，谋还岳飞兵权，先收张宪、岳云于镇江狱；十月，岳飞被逮赴行在，下大理寺狱，命御史中丞何铸、大理卿周三畏同审。",
          "岳飞入狱，掠笞备至，终不屈服，裂衣以示背上「尽忠报国」四字，何铸见其无反状，向秦桧力辩其冤；秦桧不怿，改命万俟卨主审。韩世忠闻岳飞之狱，至相府面质其罪，秦桧答曰：「飞子云与张宪书虽不明，其事体莫须有。」韩世忠怒斥：「莫须有三字，何以服天下！」狱久不决，秦桧遂自具纸条付狱中，万俟卨承其意旨，以淮西逗留、坐观胜负等辞定谳，一意坐成死狱。",
          "绍兴十一年十二月二十九日（公历1142年1月27日），岳飞赐死于大理寺狱，年三十九岁；岳云、张宪弃市于临安。岳飞家产籍没，家属流放岭南，幕僚故旧牵连得罪者数十人。一代名将，不死于抗金之野战，而死于庙堂之罗织。秦桧以莫须有之辞杀不附和议之人，其所伤不仅岳飞一身之生死，更在士林正气之摧折：冤狱既成，朝野钳口，主战之士再无立足之地，南宋恢复之志，至此消磨殆尽。"
