    interpretation: "秦桧十九年专权，非一人之奸佞所能成就，实为南宋初年特殊政治结构的产物。高宗欲和，有不可明言之隐衷：钦宗若还，帝位何安？武人若强，重演藩镇否？故秦桧之「屈己称臣」，恰为帝王承担了不便亲负之恶名。秦桧亦借君相之契，把持台谏、钳制清议，以文字狱贬斥异己，使绍兴一朝言路断绝。其代价至为深重：岁贡虽买得偏安，却使中原沦陷、忠良凋零，岳飞之死更成民族记忆中难以愈合之创伤。后世常以忠奸定秦桧之罪，然宋金力量的实际差距、南渡财政与军政之困，亦是和议成立的土壤。秦桧身死未几，王爵即夺，谥号屡改，正说明其权势所寄全在君主一念。跪像铸于西湖，骂名传于千载，既是忠奸之判，也是对权力无制、国势不振之时代的长久警省。",
