    summary: "市舶司是宋王朝管理海外贸易的专设官署，也是中国历史上第一个将海贸纳入国家财政的常设机构。开宝四年（971），宋平南汉，随即于广州置司，以知州兼使、通判兼判官。其后百年，杭州、明州、密州板桥、泉州相继设司，形成控扼东南海路的纲纪之网。其职在查验舶货、发给公凭、抽解征税、博买收购，并招徕远夷、优恤蕃商。南宋偏安江左，泉、广两市舶岁入达二百万贯，为兵费所系；泉州港遂跃为东方第一大港。市舶制度与海上丝绸之路相表里，历元、明两代而不废。",
    background: "唐开元以后，广州等口岸已设市舶使，多由宦官专领，所重在为宫廷采办海外珍奇，犀象珠翠流入内藏，与国计无大涉。五代纷扰，南汉刘氏据岭南立国，都于广州，传五主、历六十余年，财政收入颇赖海贸，市舶之利始成大宗。开宝四年（971），潘美率师灭南汉，尽有岭海之地；宋太祖不待息甲，即于广州置市舶司，以知州兼使、通判兼判官，自此海贸纳入州郡行政，宦官专领之弊遂革。太宗继之，雍熙四年（987）遣内侍八人赍敕书金帛，分四路招致海外诸蕃，政策由因任转为招徕。至神宗朝，用兵西北、开支浩繁，理财之眼遂投向大海。可以说，市舶司脱胎于唐代的宫廷采办，到宋代才真正长成国家财政的器官。",
