    interpretation: "苏辙的一生，恰与北宋士大夫政治由盛转衰的轨迹重合。嘉祐、治平间，仁宗宽厚纳谏，士以直言进身为荣，苏辙以十九岁白衣对策，即获第四等，可见其时朝堂之能容。熙宁以后，政见之争渐化为党派倾轧：新党斥旧党为因循，旧党诋新党为聚敛，而苏辙兄弟既持论公允，欲去新法之弊而不为已甚，反为两派所不容。元祐之间位列执政，蜀洛朔三党交攻，国是因人事而反复；绍圣之后，章惇、蔡京辈以编类元祐章疏治党人，于是「为子孙得两宰相」之期，终成泡影。苏辙的可贵，在于身处倾轧之中，进不以党援，退不以怨怼；其文章与政论，皆见北宋士人「以天下为己任」之精神。读《栾城集》，可见一代士大夫在治道与出处之间的为难与坚守。",
