    interpretation: "辛弃疾的一生，是南宋对「归正人」既用又防政策的典型样本。绍兴和议之后，宋廷以淮为界，岁币银绢各二十五万，主和势力长期把持权柄。来自北方的归正人，虽熟敌情、有胆略，却被视为非我族类，不得久居要冲之任、不得预闻腹心之谋。辛弃疾南归四十五年，二十三岁建奇功，六十八岁赍志以殁，其间居官不过二十余载，闲居倒近二十载，所至虽有政声，终不能一展恢复之志。他的悲剧，首先不是个人的悲剧，而是南宋一朝和战结构下的制度性悲剧。至于其词，则与他的生命完全合为一体：军旅的壮烈、田园的闲适、朝堂的郁结，尽入长短句中，故能上承苏轼、下开风气，与苏轼并称「苏辛」，存词六百二十余首，为两宋词人之冠。后人读其词，见其豪放，当更知豪放之下，皆是沉郁。",
