    interpretation: "曾巩一生，处北宋中期文治极盛之时。他上承欧阳修，下启宋文，历史地位不止在文学一端。北宋古文运动经韩愈、柳宗元奠基，欧阳修倡导，至嘉祐二年科场一变，而曾巩以典重之文成其大宗。宋文好议论、重法度的特质，在曾巩这里定型，朱熹、茅坤、姚鼐一路推崇，正因其文一出于理、可学可法。政治上，曾巩非以显赫功业见称，而以循良著称。他长于州县，所至均役、救灾、惩奸、罢贡，又以节用论理财，切中北宋财政困窘之弊。其《议经费》主张量入为出、节用为先，与王安石以开源为务的思路不同，代表北宋士大夫理财思想的另一脉络。他一生未登两府，却在文学与吏治两端，树立了传统士大夫立功立言的典范。",
