    interpretation: "宋高宗一生，怯懦与精算并存。靖康之变中的侥幸得脱，使他对金人始终心存畏惧，对武将始终心存猜防。苗刘兵变与岳飞之死，实为同一逻辑的两端：前者让他看到兵权旁落的危险，后者让他彻底收归军权。绍兴和议以称臣、岁币、划定淮水大散关之界，换得江南百年偏安，在传统史家看来是辱国之举，就当时宋金实力对比而言，却是南宋立国不得不然的现实选择。其后果有二：政治中心永久南移，临安成为十二世纪后半叶至十三世纪东亚最繁华的都会，江南经济文化全面超越北方，经济重心南移由此完成；皇位回归太祖一系，孝宗以养子继统，南宋法统得以延续。高宗个人享国三十六年、为太上皇二十五年、寿至八十一岁，是两宋皇帝中最长命者；而杀岳飞、称臣岁币、偏安一隅，也使他成为南宋最具争议的开国之君。",
