    interpretation: "理宗一朝，实为南宋由治转乱之分水岭。其继统出于权臣矫诏，故亲政之前无可奈何；端平更化虽有振作之意，真德秀、魏了翁皆理学名臣，然其人长于经术而短于谋国，朝议纷纭，于边事无大裨补。联蒙灭金之举，论者每比之北宋海上之盟：宣和联金灭辽而反召靖康之祸，端平联蒙灭金而启蒙古南侵，同蹈唇亡齿寒之覆辙，其教训在于但见世仇之可复，不见强邻之可畏。所异者，南宋犹恃川陕、荆襄、江淮山川之险，孟珙、余玠、王坚辈得以苦撑，然入洛轻进，尽丧精锐，自是战守皆处被动。其推崇理学，使程朱一跃为官方正学，元明清科举取士奉为准绳，影响此后六百年，实为理宗朝最深远之遗产。然晚年宠任贾似道，公田、楮币诸法殷削无度，国势颓敝而不可为。享国最久，亡征已具，此诚治国者之殷鉴。",
