    interpretation: "北宋之亡，非钦宗一人之罪，而钦宗之政，实加速其亡。第一次开封围城，金军孤军深入，勤王之师渐集，若君臣同心固守，未必不可却敌；然钦宗临机寡断，用李纲而旋罢，割三镇而复悔，遣使乞和又密图策反，和战两端，反覆无常，遂至两失。其病根有三：一曰猜忌自乱，钦宗既畏金人之兵，又忌太上皇与诸王，乃至李纲方胜而见黜，种师道老将见弃，亲痛仇快；二曰积弊难返，徽宗朝权奸盘踞二十余年，禁军久废训练，河北藩篱尽撤，一朝遇警，土崩瓦解；三曰和战之议挟持朝局，主和者以恤生灵为辞，主战者以雪国耻相激，庙算紊乱，进退失据。靖康之变不仅是一场军事失败，更是政治秩序与士大夫精神的全面崩溃。二帝北狩之耻，深刻塑造南宋政治心理：高宗南渡，畏武将如虎，执和议如命，皆钦宗一朝阴影所致。故《宋史》论其「疏斥正士，狎近奸谀」，实为千古定评。",
