    interpretation: "宋太宗一朝，恰是大宋国运的定调之时。其功有二：一曰完成统一，灭北汉而收吴越、漳泉，五代十国之乱局告终；一曰奠定文治，扩科举则寒门仕进路开，编类书则右文之风立，罢支郡则藩镇之祸除，士大夫政治由兹兴起，为仁宗盛世铺路。其失亦二：两番北伐皆败，精锐尽丧，宋辽攻守逆转，燕云终成两宋未竟之恨；崇文抑武、守内虚外，矫枉而过正，国势遂失汉唐之雄健。观其施政，急切有余而持重不足，盖即位合法性之焦虑始终萦绕——金匮之盟难释天下之疑，乃欲以不世军功自固，反致高梁河之创；驭将帅以猜防，用文臣以宽优，皆此心结所化。千古帝王，功过相因，于太宗见之矣。",
