    interpretation: "神宗以二十岁临御，承百年积弊之后，奋然欲扫冗官、冗兵、冗费之敝，其志不可谓不大；任王安石主持变法，推心置腹，亦不可谓不专。然变法始终受三重掣肘：积弊积重难返，非一法可除；两宫太后与元臣旧僚交章反对，皇权本身动摇；帝求治太急，既得熙河之捷，遂开好大喜功之心，五路伐夏、永乐筑城，终至丧师二十万，辱国损威。王安石两度罢相，可见变法之权在君不在臣，安石实佐帝行事之人。故熙宁之政，王安石主之；元丰之政，神宗自操之，君臣分际于此可见。后世论神宗与安石，南宋以下多归咎「祖宗之法尽坏」，至近代始有重估翻案之议，毁誉至今未定。要之，变法是非，史无定论；而新旧党争自此开其端，历元祐、绍圣、元符、崇宁，倾轧四十余年，北宋之亡实胎息于此。神宗忧愤而崩，未及见靖康之祸，然其所启之局，已不可复收。",
