      {
        heading: "龟鉴传世，泽被校雠",
        paragraphs: [
          "宋人合《太平御览》《太平广记》《文苑英华》《册府元龟》为四大书。前三书皆成于太宗朝，唯《册府元龟》成于真宗之世，而卷帙最巨、取材最严，后人或比之「史库」。北宋时书藏秘阁，外间罕见；南宋时蜀中曾复刻，明代又有刻本与活字本行世，今之完帙以明刻本为祖。清乾隆间修《四库全书》，著录于子部类书类，馆臣详加校勘。近代以来商务印书馆、中华书局先后影印出版，学者研习始便，此阁藏之巨典遂为天下公器，人人得而读之。",
          "《册府元龟》的校勘价值，清乾隆间邵晋涵从《永乐大典》辑《旧五代史》时已借其力，至近代陈垣而其用大明。陈垣著《旧五代史辑本发覆》，以是书所引《旧五代史》与四库辑本逐条比对，发其篡改、附会、讳饰之覆，遂为纠谬之名著。此外，今本《魏书》缺佚之卷，四库馆臣据是书以补之；《旧唐书》之讹文，据是书以正之；唐宋实录、诏令之不传于今者，往往于是书存其梗概。其为校勘学之渊海，沾溉后学，为学者所共称。",
          "论其影响，一则以「龟鉴」立类书之新格：前此类书如《艺文类聚》《北堂书钞》，重在备查典故；《册府元龟》则专为治道取鉴，开启了后世大型政书之先路。二则以正史为取材之宗，保存旧本，沾溉后学，其功与存佚书之《太平御览》相映成趣。然其局限亦明：取材但凭正统，排斥异闻，若干小说笔记中可贵之史料因此湮没；引文不注出处，亦给后人复核带来困难。要之，其为书也，严整有余而旁通不足，此真宗「为鉴而编」之初衷所限，亦时代风气使然。"
        ]
      }
