    interpretation: "《册府元龟》的独特价值，在于它是「为鉴而编」的类书。唐宋类书如《艺文类聚》《太平御览》以备查博闻为务，所重在「全」；《册府元龟》以治道劝惩为务，所重在「严」。这一取材原则使它成为一部以正史为唯一来源的君臣行为大典：三十一部自帝王至外臣的排序，本身就是一幅秩序井然的政治图景；不录小说野史，则保证了史料的可靠性，也付出了牺牲民间记载的代价。它最大的贡献在文献保存：所引十七史多为宋初监本，早于今传诸本，脱误未生，故能正今本之讹、补今本之缺。清代辑《旧五代史》，近人陈垣著《旧五代史辑本发覆》，皆以此为渊海。它上承《通典》以制度为纲的遗意，下启《永乐大典》之巨制，虽以类书名，实具史裁，在中国典籍史上自成一格。",
