        heading: "门类秩序四书分途",
        paragraphs: [
          "《御览》部类次序并非随意排比，而是一套秩序井然的知识谱系：天部居首，次时序、次地，示天尊地卑、四时流转；皇王、偏霸、封建、职官继之，明正统与僭伪之别、王朝制度之详；人事、逸民以下，序人伦教化、礼乐刑政；释道二部并列，见三教并崇之势；居处、器物、舟车、兵阵，备日常百物与武备；休征、咎征、神鬼、妖异，寓天人感应；兽、禽、鳞介、虫豸、草木、果菜、香药殿后，博物之学置于全编之末。天地、王道、人事、百物依次铺陈，暗合王朝治理所需的知识等级。",
          "其纂例亦精：每类之下，先列书名，再录其事其文；引书多整段抄撮，少加删改，虽不免辗转传抄之误，却因此保存古籍原貌。引用书目一千六百九十余种，为历来类书之冠；若并诗赋文章计之，则有二千八百余种之说，学者两存其异。所引兼包经史子集、传记、地志、小说，上溯先秦，下逮五代，唐以前文献什九在焉。此等取材广度，使《御览》不止是工具书，更近乎一座缩微的北宋前期图书总库。",
          "太平兴国至大中祥符间，太宗、真宗先后敕修四部大书，各司其职：《太平御览》总汇天地事物，《太平广记》专集稗官小说，《文苑英华》继《文选》之后荟萃历代文章，太平兴国九年（984）九月诏修、雍熙三年（986）十二月成书一千卷；《册府元龟》专录历代君臣事迹与政理，景德二年（1005）九月王钦若、杨亿等奉敕编修，大中祥符六年（1013）十一月成一千卷。四书浩博，同出宋初右文之政，而《御览》成书最早，居宋初四大书之首。"
        ]
