    interpretation: "《太平御览》的意义远超一部类书。太宗以日览三卷的亲读姿态向天下宣示崇儒右文之诚，背后是一套精心设计的文化政治：修书可消弭武将干政之患，吸纳南唐、西蜀旧臣入馆阁，以文化整合先行于军事统一；十四位纂臣中徐铉、汤悦本南唐词臣，正见新朝用人不拘一统。五十五部以天、地、皇王、人事、百物为序，将王朝所需知识体系统摄于御览之名下，类书由此成为知识权力的象征。然其书引文多辗转抄撮、不注篇卷，鲁鱼亥豕之误在所难免，学者用之须审。其最大功绩终在保存亡书：所引十之七八今已不存，明清以来辑佚学者如马国翰、茆泮林多取资于此，故世推为辑佚校勘之渊薮，与《永乐大典》《四库全书》同属中国古代文献保存之重器。",
