        paragraphs: [
          "此书最可瞩目者，为前集卷十二所载三种火药配方：毒药烟球用焰硝三十两、硫黄十五两、木炭五两，佐以草乌头、狼毒、巴豆、砒霜等毒物；蒺藜火球用焰硝二十五两、硫黄十一两、木炭五两半，和以沥青、桐油，内藏铁蒺藜；火炮火药则用焰硝四十两、硫黄十四两、木炭十四两，杂以竹茹、麻茹、清油、黄丹等物。三者皆为硝、硫、炭三元体系，硝的比例约占四至六成，已具黑火药的基本配比特征；书中又详载炮制捣合之法与辅料配伍，并附绘火药兵器图样，记其形制用法。",
          "以这三类火药兵器言：毒药烟球以抛石机投掷，燃烧生烟，散布毒雾以熏扰敌阵；蒺藜火球炸裂之后，铁蒺藜散布满地，以阻遏西夏骑兵冲突；火炮则是以火药包装于抛掷物中，焚毁城楼寨栅。三者皆为燃烧性、烟毒性兵器，尚非后世爆炸性火器，然已正式列装于宋军行伍，用于城守攻战。《武经总要》因此成为世界现存最早、最完整的火药武器官方文献，比英国罗吉尔·培根记载火药配方早约二百年，标志火药自炼丹方术正式跨入战场，中国古代火器史由此开篇。",
          "此书的影响不止于火药。其五路边防图与山川城寨图，是研究北宋西北军事地理的珍贵舆图；其制度与战例的编纂体例，为明代《武备志》等兵书所继承。宋神宗元丰三年（1080），朝廷又校定《孙子》等七书刻印颁行，号《武经七书》，与《武经总要》同为宋代武学教育的经典，共同构成官修武学典籍的体系。今传明正统四年（1439）司礼监刻本、《四库全书》本及日本所藏南宋残本，使此书典籍生命延续千年，至今仍是研究宋代军制、军事技术与中西火器交流史不可绕过的基本文献。"
        ]
