    interpretation: "《武经总要》的深层价值，须置于北宋建军理念的矛盾之中理解。宋初惩晚唐藩镇之弊，收兵权、抑武将，更戍流转，将兵分离；至仁宗朝，这一体制在宋夏战争中暴露无遗。仁宗以官修兵书整军，实是以国家编纂取代将门私授、以文本知识弥补将领经验之失，折射出崇文抑武体制下对武备的规训与焦虑。书中于历代兵法之外，备载本朝制度与战例，正是欲以可操作的规程，重塑一支能战之师。其最深远的影响在火药。三种配方虽以燃烧、烟毒为主，距管状火器尚远，却标志着火药正式从道家炼丹之术转入军事列装，中国古代火器史由此开篇；在世界范围内，这是现存最早的官方火药武器记载，早于欧洲约两个世纪。书中五路边防图与城寨堡铺的记录，亦为宋代舆地学与西北军事地理研究保存了不可替代的材料。要之，此书既是北宋中期边防危机的产物，也是中国古代军事知识由经验传授走向典籍总集的枢纽。",
