    interpretation: "更戍法之立与废，实为宋室基本国策之缩影。其设计逻辑，防内重于御外：以兵将分离消弭兵变，以内外相维维持皇权。就其本意而言，可谓成功——终宋之世，未再现唐末五代藩镇割据、军阀篡位之局，兵权归于朝廷，将帅无久握之柄。然其代价，则是国防之不振。对辽、对夏作战屡败，高梁河、岐沟关、三川口、好水川，其败虽各有近因，而兵不识将、将不知兵之制度，实为根本之因。且三年一易、往来劳费，兵额日增而国用日匮，冗兵之费遂与冗官、冗员并为国家膏肓之疾。熙宁将兵法虽矫其弊，兵将相知，军势稍振，然北宋未及尽收其效而遭靖康之变，南渡以后，军制又一变。后世论宋，谓其内治最安而外御最弱，源皆肇于此。",
