    interpretation: "度宗一朝之失，约有四端，皆非偶然。其一为继承之弊：理宗诸子早夭，迫于宗法血亲之近，立先天受损之侄为储，明知其智力下材而仍付以大统，皇位继承只论亲疏、不论贤愚，此为制度之病根。其二为权相之弊：度宗以「师臣」之礼待贾似道，朝见答拜而不名，平章军国重事总揽大权，三日一朝，政出私门，相权凌驾君权之上，台谏又为天子耳目，却被权相尽逐，于是君臣之间再无制衡。其三为信息之弊：襄阳被围六年，告急之报尽匿不上闻，凡言边事者辄贬，朝堂壅蔽，帝王不知国危，此为决策机制之坏死。其四为边备之弊：吕文德受通商之愚，许开榇场，反使蒙古筑城围困；襄樊一失，长江门户洞开，南宋防线自此崩解。四弊相因而成，南宋最后十年君臣失格，国势遂不可救，可为后世深鉴。",
