    interpretation: "宁宗一朝三十年，实为南宋由守成走向崩坏的枢纽，其病理在于皇权庸弱而相权独大。宁宗不习治体，批答臣下但云「商量」，军国大事一委权臣。韩侂胄以拥立之功外结戚里、内抑言路，以「伪学」之名尽逐正人，是权相之狂悖；史弥远以诛韩之功矫诏废立，擅权二十六年，是权相之阴鸷。一显一晦，而皇权皆为玩物。开禧北伐是轻启边衅的豪赌：师出仓促、将非其人、准备不足，虽有毕再遇等之勇，终致江淮糜烂；其代价是嘉定和议中伯侄之称、岁币三十万、犒军钱三百万贯，并函首权臣以送敌国，国体扫地。然庆元党禁之迫害，反使理学在民间根基愈深，嘉定后解禁追崇，至理宗朝定为官学——思想史与政治史在此呈反向运动：政治上皇权式微、权臣窃柄，思想上程朱之学却由厄而兴，终成后世七百年之正统，此宁宗朝最耐寻味之处。",
