    background: "赵煦生于熙宁十年（1077），为神宗第六子，母朱德妃。神宗在位十八年，以富国强兵为志，王安石变法推行已逾十年，青苗、免役、市易、保甲诸法遍行天下；对外则五路伐夏，然元丰五年（1082）永乐城之败，丧师二十余万，神宗深感痛愤，自此起居失调，元气大伤。元丰七年（1084）延安郡王佣出阁就傅，元丰八年（1085）正月神宗不豫，二月乃立为皇太子，赐名煦。神宗弥留之际，宰相王珪、蔡确等请皇太后高氏权同听政。高氏为英宗皇后，出身勋旧，素以祖宗法度为本，不喜新法，与司马光、文彦博等元老遥相呼应。神宗朝新旧两党角力已十余年：新党以王安石、吕惠卿、章惇为首，力主变法开边；旧党以司马光、文彦博为宗，主张省法息兵、恤民固本。十岁幼帝践祚，皇权、相权与太后垂帘之制三方交错，遂为元祐更化与绍圣绍述两番大反复埋下伏笔。",
