          "司马光秉政，以尽废新法为急务。元祐元年（1086）春，罢保甲、方田均税、市易、保马诸法；秋，罢青苗法，复常平籴粜旧制。免役法之废，争论尤剧：光主尽复差役，章惇以「百姓习惯免役日久，遽改不便」驳之，曾布亦持两端，光不听，卒于是年十月罢免役法。未几，市易、保甲、将官诸法次第罢废，熙丰十五年新政，一年之间芟夷殆尽，旧史谓之「元祐更化」。司马光秉政日短，而更张之速、议论之专，实有宋一代所仅见。",
          "然旧党秉政不久，内部分裂。程颐以崇政殿说书侍帝侧，严毅寡恩；苏轼为翰林学士，诙谐不羁，遂成洛蜀二党之隙。元祐二年（1087）九月，苏轼试馆职策题「师仁祖之忠厚，法神考之励精」之问出，朱光庭、贾易等弹轼谤讪先帝，洛蜀朔三党交章互攻，台谏风闻言事，一斥不复。苏轼出知杭州，程颐罢经筵归洛阳，刘挚、梁焘、王岩叟等朔党主政于中，元祐之政渐为门户之争所掩，国是因之益纷。",
