    interpretation: "哲宗一朝，是北宋党争由政见之争堕落为门户倾轧的分水岭。元祐更化与绍圣绍述两次大反复，表面是法度罢复之争，实质是皇权与垂帘体制、新党与旧党之间权力格局的重构。司马光以「母改子之政」为名，一年尽废新法，操之过急；章惇辈以「绍述」为号，追贬发墓、籍党立碑，报施相半。当政见可以讨论时，党争尚有底线；一旦固化为党籍，则凡元祐之人必逐、凡熙丰之法必复，国政遂成倾轧之具。军事上，绍圣、元符间章楶进筑浅攻，平夏城一捷使西夏乞和、复四寨之地，为神宗以来对夏武功之最，然连年进筑，国帑民力耗损亦巨。哲宗以冲龄践祚，十五年间未得一展其志，二十四岁无嗣而崩，端王佶以轻佻继之，北宋最需要守成持重之时，恰逢最不堪守成之主，亡国之祸已伏于此。",
