    summary: "海上之盟是北宋徽宗朝与女真金国订立的夹攻辽国之约，因宋金使节自登州（今山东蓬莱）渡渤海往来，史称海上之盟。重和元年（1118）宋遣马政使金通意，宣和二年（1120）赵良嗣使金定约：金取辽中京大定府，宋取燕京析津府并西京大同府；灭辽后宋将原输辽之岁币五十万（银二十万两、绢三十万匹）转输于金，燕云十六州归宋。然宋军两攻燕京皆大败，金人尽窥宋军之虚，燕京终由金军自取；宋以百万贯代租钱赎回空城，仅得涿、易、檀、顺、景、蓟六州二十四县。宣和五年（1123）交割后不久，张觉事件令宋失信于金，宣和七年（1125）金两路南侵，靖康之祸遂起。此盟被视为北宋末年最大的战略误判，与一百二十年后南宋联蒙灭金（端平入洛）如出一辙。",
    background: "澶渊之盟（景德二年，1005）后，宋辽通好百余年，边境晏然，岁币成为维持和平的成本。至徽宗朝，蔡京、童贯以「丰亨豫大」与「复燕云」相倡，徽宗久有恢复汉唐旧疆之志。辽道宗、天祚帝两朝昏暗，女真完颜部在东北崛起，阿骨打于收国元年（1115）称帝建国，号大金，连破辽军。辽朝统治摇摇欲坠的消息传入宋廷，童贯等以辽为必亡之国，欲乘隙取燕云十六州，成不世之功。辽籍燕人马植（后赐名赵良嗣）窥准宋廷心意，献联金灭辽之策，正中徽宗、童贯下怀。宋廷遂决意背弃对辽百年之约，跨海结好女真，海上之盟由此而起。",
