          "马植入宋后，易姓名为李良嗣，藏匿于童贯府中。童贯荐之于朝，徽宗召对，李良嗣力陈辽国必亡之状，请王师一出，复中国往昔之疆。徽宗大悦，于政和五年（1115）赐姓赵，名良嗣，擢秘书丞，自此君臣以平燕为已有之局。朝中老臣多不以为然，谓辽虽弱，百年盟约不可轻弃，女真虎狼之邦，结之恐贻后患，然徽宗与童贯、蔡京一意孤行，弗恤也。",
          "宋金之间本无通路，陆路皆为辽土所隔，唯登州（今山东蓬莱）渡渤海可抵女真。重和元年（1118）八月，徽宗遣武义大夫马政、平海军指挥使呼延庆自登州渡海使金，以市马为名，通好女真。金太祖阿骨打见宋使至，亦遣渤海人李善庆等随宋使入汴京报聘。宋金始通使节，往返皆经海上，故此盟约史称「海上之盟」。宋廷自此走上联金灭辽之途，辽国亦渐知宋之意图，而宋之祸机已伏。"
