          "童贯败后，不敢再战，遣使招降辽燕京君臣，萧干、耶律大石等不从。是年九月，辽常胜军首领郭药师以涿州来降，宋廷大喜，以为燕京可图。十月，童贯命都统制刘延庆统兵十万，再攻燕京，军于卢沟以南。郭药师献计，自暗门袭燕京，入城巷战，萧干回军反扑，郭药师兵败坠城，几不得脱。刘延庆拥兵十万，观望不前，畏懦无谋，两军相持于卢沟。",
